INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-tokoro-1', 'sent-ex-tokoro-1', 'en', 'I am just about to go out.', 'authored'),
  ('st-ex-tokoro-2', 'sent-ex-tokoro-2', 'en', 'I am in the middle of eating.', 'authored'),
  ('st-ex-tokoro-3', 'sent-ex-tokoro-3', 'en', 'I have just got back.', 'authored'),
  ('st-ex-tokoro-4', 'sent-ex-tokoro-4', 'en', 'The meeting has only just finished.', 'authored'),
  ('st-ex-baai-1', 'sent-ex-baai-1', 'en', 'In the event of rain it is cancelled.', 'authored'),
  ('st-ex-baai-2', 'sent-ex-baai-2', 'en', 'If you are going to be late, please ring.', 'authored'),
  ('st-ex-baai-3', 'sent-ex-baai-3', 'en', 'If you do not understand, please ask the teacher.', 'authored'),
  ('st-ex-baai-4', 'sent-ex-baai-4', 'en', 'If you are ill, please stay off.', 'authored'),
  ('st-ex-oninaru-1', 'sent-ex-oninaru-1', 'en', 'The teacher has already gone home.', 'authored'),
  ('st-ex-oninaru-2', 'sent-ex-oninaru-2', 'en', 'The department head is taking today off.', 'authored'),
  ('st-ex-oninaru-3', 'sent-ex-oninaru-3', 'en', 'The company president is going out tomorrow.', 'authored'),
  ('st-ex-oninaru-4', 'sent-ex-oninaru-4', 'en', 'The teacher has just arrived.', 'authored'),
  ('st-ex-osuru-1', 'sent-ex-osuru-1', 'en', 'I will bring it tomorrow.', 'authored'),
  ('st-ex-osuru-2', 'sent-ex-osuru-2', 'en', 'I will see you as far as the station.', 'authored'),
  ('st-ex-osuru-3', 'sent-ex-osuru-3', 'en', 'I will ring you later.', 'authored'),
  ('st-ex-osuru-4', 'sent-ex-osuru-4', 'en', 'I will ask the teacher.', 'authored'),
  ('st-ex-meirei-1', 'sent-ex-meirei-1', 'en', 'Get over here.', 'authored'),
  ('st-ex-meirei-2', 'sent-ex-meirei-2', 'en', 'Be quiet.', 'authored'),
  ('st-ex-meirei-3', 'sent-ex-meirei-3', 'en', 'Eat up.', 'authored'),
  ('st-ex-meirei-4', 'sent-ex-meirei-4', 'en', 'Read the book.', 'authored'),
  ('st-ex-kinshina-1', 'sent-ex-kinshina-1', 'en', 'Do not go into the room.', 'authored'),
  ('st-ex-kinshina-2', 'sent-ex-kinshina-2', 'en', 'Do not eat nothing but meat.', 'authored'),
  ('st-ex-kinshina-3', 'sent-ex-kinshina-3', 'en', 'Do not open the window.', 'authored'),
  ('st-ex-kinshina-4', 'sent-ex-kinshina-4', 'en', 'Do not talk on the train.', 'authored'),
  ('st-ex-garu-1', 'sent-ex-garu-1', 'en', 'My little brother wants new shoes.', 'authored'),
  ('st-ex-garu-2', 'sent-ex-garu-2', 'en', 'My little sister is afraid of dogs.', 'authored'),
  ('st-ex-garu-3', 'sent-ex-garu-3', 'en', 'The children are feeling the cold.', 'authored'),
  ('st-ex-garu-4', 'sent-ex-garu-4', 'en', 'My older brother feels the heat.', 'authored'),
  ('st-ex-nominal-1', 'sent-ex-nominal-1', 'en', 'I like reading books.', 'authored'),
  ('st-ex-nominal-2', 'sent-ex-nominal-2', 'en', 'I like swimming.', 'authored'),
  ('st-ex-nominal-3', 'sent-ex-nominal-3', 'en', 'Getting up early is hard.', 'authored'),
  ('st-ex-nominal-4', 'sent-ex-nominal-4', 'en', 'I am waiting for my older brother to come.', 'authored'),
  ('st-ex-gimonka-1', 'sent-ex-gimonka-1', 'en', 'Did somebody come?', 'authored'),
  ('st-ex-gimonka-2', 'sent-ex-gimonka-2', 'en', 'Did you eat anything?', 'authored'),
  ('st-ex-gimonka-3', 'sent-ex-gimonka-3', 'en', 'Did you go anywhere?', 'authored'),
  ('st-ex-gimonka-4', 'sent-ex-gimonka-4', 'en', 'Please ask somebody.', 'authored'),
  ('st-ex-youtosuru-1', 'sent-ex-youtosuru-1', 'en', 'I was about to go out, and then it rained.', 'authored'),
  ('st-ex-youtosuru-2', 'sent-ex-youtosuru-2', 'en', 'I tried to eat it, but I could not.', 'authored'),
  ('st-ex-youtosuru-3', 'sent-ex-youtosuru-3', 'en', 'My older brother is trying to get to Japan.', 'authored'),
  ('st-ex-youtosuru-4', 'sent-ex-youtosuru-4', 'en', 'Just as I was dropping off to sleep, the phone rang.', 'authored'),
  ('st-ex-soumonai-1', 'sent-ex-soumonai-1', 'en', 'There is no sign of making it in time today.', 'authored'),
  ('st-ex-soumonai-2', 'sent-ex-soumonai-2', 'en', 'The meeting shows no sign of ending.', 'authored'),
  ('st-ex-soumonai-3', 'sent-ex-soumonai-3', 'en', 'My older brother does not look likely to come.', 'authored'),
  ('st-ex-soumonai-4', 'sent-ex-soumonai-4', 'en', 'I do not look like finishing the book.', 'authored')
